mapper.select:
SELECT CHANCE_ID, CREDIT_LINE_NUMBER, CREDIT_LINE_NAME, DOCUMENT_TYPE, CREDIT_LINE_AMT, VALID_FROM, VALID_TO, DESCRIPTION, PRJ_INFO_DESC, BP_ID, PROJECT_ASSISTANT, ( select hbm.BP_NAME from HLS_BP_MASTER hbm where hbm.BP_ID = HCLC.BP_ID ) BP_ID_N, CREDIT_LINE_STATUS, CURRENCY_CODE, ( SELECT FE.NAME FROM FND_EMPLOYEE FE WHERE FE.EMPLOYEE_ID=HCLC.PROPOSER_EMPLOYEE_ID )AS projectManager,
( SELECT FE.NAME FROM FND_EMPLOYEE FE WHERE FE.EMPLOYEE_ID=HCLC.PROJECT_ASSISTANT )AS projectAssistantName, ( SELECT FE.NAME FROM FND_EMPLOYEE FE WHERE FE.EMPLOYEE_ID=HCLC.PROJECT_ASSISTANT )AS projectAssistantN, ( SELECT HBM.BP_CODE FROM HLS_BP_MASTER HBM WHERE HBM.BP_ID=HCLC.BP_ID )AS clientCode, ( SELECT HBM.BP_NAME FROM HLS_BP_MASTER HBM WHERE HBM.BP_ID=HCLC.BP_ID )AS clientName, ( SELECT FOU.UNIT_NAME FROM FND_ORG_UNIT FOU, FND_EMPLOYEE_ASSIGNS FEA WHERE FEA.EMPLOYEE_ASSIGN_ID=HCLC.PROPOSER_EMPLOYEE_ASSIGN_ID AND FOU.UNIT_ID=FEA.UNIT_ID )AS unitName, ( SELECT distinct D.NAME FROM FND_EMPLOYEE_ASSIGNS A, FND_ORG_UNIT B, FND_EMPLOYEE_ASSIGNS C, FND_EMPLOYEE D WHERE A.EMPLOYEE_ASSIGN_ID = HCLC.PROPOSER_EMPLOYEE_ASSIGN_ID AND A.UNIT_ID = B.UNIT_ID AND B.CHIEF_POSITION_ID = C.POSITION_ID AND C.EMPLOYEE_ID = D.EMPLOYEE_ID AND C.ENABLED_FLAG = 'Y' )AS managerName, ( SELECT FC.COMPANY_FULL_NAME FROM FND_COMPANY FC WHERE FC.COMPANY_ID=HCLC.COMPANY_ID )AS companyName, ( SELECT FC.CURRENCY_NAME FROM FND_CURRENCY FC WHERE FC.CURRENCY_CODE=HCLC.CURRENCY_CODE )AS currencyName, ( SELECT FC.CURRENCY_NAME FROM FND_CURRENCY FC WHERE FC.CURRENCY_CODE=HCLC.CURRENCY_CODE )AS currencyCodeN, ( SELECT HDT.DESCRIPTION FROM HLS_DOCUMENT_TYPE HDT WHERE HDT.DOCUMENT_TYPE=HCLC.DOCUMENT_TYPE AND HDT.DOCUMENT_CATEGORY=HCLC.DOCUMENT_CATEGORY AND HDT.BUSINESS_TYPE=HCLC.BUSINESS_TYPE )AS documentDesc, ( SELECT HDT.DESCRIPTION FROM HLS_DOCUMENT_TYPE HDT WHERE HDT.DOCUMENT_TYPE=HCLC.DOCUMENT_TYPE AND HDT.DOCUMENT_CATEGORY=HCLC.DOCUMENT_CATEGORY AND HDT.BUSINESS_TYPE=HCLC.BUSINESS_TYPE )AS documentTypeN, HCLC.company_id, OBJECT_VERSION_NUMBER FROM HLS_CREDIT_LINE_CHANCE HCLC
1=1
and HCLC.CHANCE_ID = #{chanceId}
and HCLC.company_id =#{companyId}

SELECT CLC.CHANCE_ID, CLC.BP_ID, ( SELECT HBM.BP_NAME FROM HLS_BP_MASTER HBM WHERE CLC.BP_ID = HBM.BP_ID ) AS BP_NAME, CLC.CREDIT_LINE_NUMBER, CLC.CREDIT_LINE_NAME, ( SELECT FC.COMPANY_FULL_NAME FROM FND_COMPANY FC WHERE CLC.COMPANY_ID = FC.COMPANY_ID ) AS COMPANY_NAME, CLC.CREDIT_LINE_AMT, CLC.CREDIT_EXPOSURE_AMT, CLC.VALID_FROM, CLC.VALID_TO, CLC.CREDIT_LINE_STATUS, ( SELECT HDS.DESCRIPTION FROM HLS_DOCUMENT_STATUS HDS WHERE HDS.DOCUMENT_CATEGORY = 'FCT_PROJECT' AND HDS.STATUS_CODE = CLC.CREDIT_LINE_STATUS ) AS CREDIT_LINE_STATUS_DESC, CLC.CREATION_DATE touch_created_date FROM HLS_CREDIT_LINE_CHANCE CLC
1=1 AND CLC.company_id = #{request.companyId} AND CLC.DOCUMENT_CATEGORY='HLS_CREDIT_LINE'
and CLC.CREDIT_LINE_STATUS=#{creditLineStatus}
and CLC.CREDIT_LINE_AMT >= #{limitFrom}
and CLC.CREDIT_LINE_AMT <= #{limitTo}
and CLC.VALID_FROM >= #{beginDate}
and CLC.VALID_TO < (#{endDate} + 1)
and ( SELECT HBM.BP_NAME FROM HLS_BP_MASTER HBM WHERE CLC.BP_ID = HBM.BP_ID ) like concat(concat('%',#{bpName}),'%')
order by clc.creation_date desc
